-- ==========================================================================================
-- Melengkapi Customer Master dari Compile.csv
-- ==========================================================================================
-- Sesudah 20260929010000 masih tersisa satu baris rusak: pelanggan 617493 UD.SENTOSA dengan
-- nomor rekening 1.7601E+13. Baris pelanggan itu ada di ListCust.csv tetapi kolom rekeningnya
-- kosong di sana, sehingga tidak ada yang bisa diambil. Nilai benarnya ternyata ada di
-- Compile.csv: 017601000020562 - perhatikan nol di depannya, yang juga ikut hilang saat impor.
--
-- Karena itu berkas ini melengkapi public.customers dari Compile.csv, sumber kedua yang
-- memuat data pelanggan yang sama. Aturannya tetap sama dan tetap hati-hati: sebuah nilai
-- hanya diisi bila yang sekarang kosong atau berbentuk eksponen. Nilai yang sudah benar tidak
-- pernah ditimpa, dan tidak ada baris yang ditambah maupun dihapus.
--
-- Bila satu kode pelanggan muncul beberapa kali di Compile.csv, yang dipakai adalah baris
-- dengan sel terisi terbanyak, supaya satu baris yang kebetulan kosong tidak mengalahkan baris
-- yang lengkap.
--
-- Aman dijalankan berulang.
-- ==========================================================================================

drop table if exists rc_sumber_cust2;
create temporary table rc_sumber_cust2(
  customer_code text primary key, ktp text, npwp text, no_rek text, nama_rek text,
  bank text, top_text text
) on commit drop;


create or replace temporary view rc_pola_c2 as select '^[0-9]+([.][0-9]+)?[Ee][+-]?[0-9]+$' as p;

update public.customers c
   set ktp            = case when nullif(x.ktp,'') is not null
                              and (coalesce(c.ktp,'')='' or c.ktp ~ (select p from rc_pola_c2))
                             then x.ktp else c.ktp end,
       npwp           = case when nullif(x.npwp,'') is not null
                              and (coalesce(c.npwp,'')='' or c.npwp ~ (select p from rc_pola_c2))
                             then x.npwp else c.npwp end,
       account_number = case when nullif(x.no_rek,'') is not null
                              and (coalesce(c.account_number,'')='' or c.account_number ~ (select p from rc_pola_c2))
                             then x.no_rek else c.account_number end,
       account_name   = case when nullif(x.nama_rek,'') is not null and coalesce(c.account_name,'')=''
                             then x.nama_rek else c.account_name end,
       bank           = case when nullif(x.bank,'') is not null and coalesce(c.bank,'')=''
                             then x.bank else c.bank end,
       top_text       = case when nullif(x.top_text,'') is not null
                              and (coalesce(c.top_text,'')='' or c.top_text ~ (select p from rc_pola_c2))
                             then x.top_text else c.top_text end,
       updated_at     = now()
  from rc_sumber_cust2 x
 where c.customer_code = x.customer_code;

create or replace function rc_private.marker_20260930() returns boolean
language sql immutable set search_path='' as $$select true$$;
revoke all on function rc_private.marker_20260930() from public,anon;
grant execute on function rc_private.marker_20260930() to authenticated;

-- Seluruh angka eksponen di bawah ini harus nol.
select 'Customer Master dilengkapi dari Compile.csv' as hasil,
 (select count(*) from public.customers where ktp ~ (select p from rc_pola_c2)) as ktp_eksponen,
 (select count(*) from public.customers where npwp ~ (select p from rc_pola_c2)) as npwp_eksponen,
 (select count(*) from public.customers where account_number ~ (select p from rc_pola_c2)) as rekening_eksponen,
 (select account_number from public.customers where customer_code='617493') as cek_617493,
 (select count(*) from public.customers where coalesce(btrim(account_number),'')<>'') as ber_rekening,
 (select count(*) from public.customers where coalesce(btrim(top_text),'')<>'') as ber_top;
